import{w as n}from"./index-BprwxzqU.js";async function t(){return(await n.get("/transfers/pending")).data.data.map(s=>({id:s.id,sessionId:s.session_id,userId:s.user_id,reason:s.reason||"未记录原因",conversationSummary:s.conversation_summary||"",createdAt:s.created_at,status:"pending"}))}async function r(e){return(await n.get(`/sessions/${e}/messages`)).data.data.map(a=>({role:a.role,content:a.content,createdAt:a.created_at}))}async function o(e){const s=await n.post(`/transfers/${e}/accept`);if(s.data.code!==0)throw new Error(s.data.message||"接单失败")}async function c(e){const s=await n.post(`/transfers/${e}/close`);if(s.data.code!==0)throw new Error(s.data.message||"关闭失败")}async function d(e,s){const a=await n.post(`/sessions/${e}/reply`,null,{params:{content:s}});if(a.data.code!==0)throw new Error(a.data.message||"发送失败")}const p={listPendingTransfers:t,getSessionMessages:r,acceptTransfer:o,closeTransfer:c,sendHumanReply:d};export{p as t};
